  ('areq_8ea3158b58e7ec3394e80acb', 'WEBELOS', 'Let''s Camp', NULL::text, '8', 'Recite the Outdoor Code and Leave No Trace Principles for Kids from Memory.', NULL::integer, FALSE, 8::integer),
  ('areq_4dc677d9dfa021cc5bbe5c48', 'WEBELOS', 'Let''s Camp', NULL::text, '9', 'After your campout, share the things you did to follow the Outdoor Code and Leave No Trace Principles for Kids with your den or family.', NULL::integer, FALSE, 9::integer),
  ('areq_1bf17504c69b21ff03a77be5', 'WEBELOS', 'Math on the Trail', NULL::text, '1', 'Determine your walking pace by walking ¼ mile. Make a projection on how long it would take you to walk 2 miles.', NULL::integer, FALSE, 1::integer),
