  ('areq_3cad29e35ee7ffbb2cf029a8', 'WEBELOS', 'Math on the Trail', NULL::text, '3', 'Make a projection on how long it would take you to hike a 20-mile trail over two days. List all the factors to consider for your projection.', NULL::integer, FALSE, 3::integer),
