  ('areq_3f1d2cc1a60bbcdb1acf2c99', 'WEBELOS', 'Modular Design', NULL::text, '3', 'Using the model made in requirement 2, create a set of step-by-step instructions on how to make your model.', NULL::integer, FALSE, 3::integer),
  ('areq_cff3442305b648cfa4fd1714', 'WEBELOS', 'Modular Design', NULL::text, '4', 'Have someone make your model using your instructions.', NULL::integer, FALSE, 4::integer),
