  ('areq_65ed97761b2ab078ec8c78fc', 'WEBELOS', 'Paddle Onward', NULL::text, '1', 'Before attempting requirements 5, 6, 7, 8 and 9 for this Adventure, you must pass Scouting America swimmer test.', NULL::integer, FALSE, 1::integer),
