  ('areq_dcffd51a848977ac2993322d', 'AOL', 'Bobcat', NULL::text, '2', 'Get to know members of your patrol.', NULL::integer, FALSE, 2::integer),
  ('areq_ab5b3ecfee0320a4dc4d9aa1', 'AOL', 'Bobcat', NULL::text, '3', 'Recite the Scout Oath and Scout Law with your patrol.', NULL::integer, FALSE, 3::integer),
  ('areq_f1945719ce06c90663b01cca', 'AOL', 'Bobcat', NULL::text, '4', 'With your patrol create a Code of Conduct.', NULL::integer, FALSE, 4::integer),
  ('areq_828e75644f561b86a9145a11', 'AOL', 'Bobcat', NULL::text, '5', 'Demonstrate the Scout sign, Scout salute and Scout handshake used by Scouting America. Show how each are used.', NULL::integer, FALSE, 5::integer),
  ('areq_75ac2530fef0b1b20ba7be6f', 'AOL', 'Bobcat', NULL::text, '6', 'Learn the Scouting America slogan and motto.', NULL::integer, FALSE, 6::integer),
