  ('areq_55bae78c7aec962f6a5f25be', 'AOL', 'Bobcat', NULL::text, '8', 'At home, with your parent or legal guardian do the activities in the booklet “How to Protect Your Children from Child Abuse: A Parent’s Guide.”', NULL::integer, FALSE, 8::integer),
  ('areq_06bab76329d93a54fa0591c5', 'AOL', 'Outdoor Adventurer', NULL::text, '1', 'Learn about the Scout Basic Essentials.', NULL::integer, FALSE, 1::integer),
  ('areq_698202b2fff46c181b9ff82c', 'AOL', 'Outdoor Adventurer', NULL::text, '2', 'Determine what you will bring on an overnight campout — including a tent and sleeping bag/gear — and how you will carry your gear.', NULL::integer, FALSE, 2::integer),
  ('areq_b977ec3576663c0778f22412', 'AOL', 'Outdoor Adventurer', NULL::text, '3', 'Review the four points of Scouting America’s SAFE Checklist and how you will apply them. on the campout.', NULL::integer, FALSE, 3::integer),
  ('areq_a88c6bc9e0ab0036ad24ada9', 'AOL', 'Outdoor Adventurer', NULL::text, '4', 'Locate the campsite where you will be camping on a map.', NULL::integer, FALSE, 4::integer),
