  ('areq_b335aeba2da79949cfe70fc3', 'AOL', 'Outdoor Adventurer', NULL::text, '7', 'Explain how to keep food safe and the kitchen area sanitary at the campsite. Demonstrate your knowledge during the campout.', NULL::integer, FALSE, 7::integer),
  ('areq_25a800de9f8598ab0e511d4d', 'AOL', 'Outdoor Adventurer', NULL::text, '8', 'After your campout, discuss with your patrol what went well and what you would do differently next time. Include how you followed the Outdoor Code and Leave No Trace Principles for Kids.', NULL::integer, FALSE, 8::integer),
